"""Print the next order id to stdout.

Reads ids.txt (one ORD-XXXX id per line, most recent last),
increments the last id's 4-character base36 suffix by 1,
and prints "ORD-" + the result.
"""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
ID_WIDTH = 4


def to_base36(n: int) -> str:
    """Convert a non-negative integer to an uppercase base36 string."""
    if n == 0:
        return "0"
    digits = []
    while n:
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert an uppercase base36 string to an integer."""
    return int(s, 36)


def main() -> None:
    try:
        with open("ids.txt", "r") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # No ids issued yet — start from zero.
        next_suffix = "0".zfill(ID_WIDTH)
    else:
        last = lines[-1]
        if not last.startswith("ORD-") or len(last) != 5 + ID_WIDTH:
            print(f"Error: malformed id {last!r}", file=sys.stderr)
            sys.exit(1)
        suffix = last[4:]
        num = from_base36(suffix)
        num += 1
        next_suffix = to_base36(num).zfill(ID_WIDTH)
        if len(next_suffix) > ID_WIDTH:
            print("Error: id overflow (no more 4-character ids)", file=sys.stderr)
            sys.exit(1)

    sys.stdout.write(f"ORD-{next_suffix}\n")


if __name__ == "__main__":
    main()

