"""Generate manifest.json: a mapping of release/ file paths to SHA-256 hex digests."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_hexdigest(file_path: Path) -> str:
    """Return the SHA-256 hex digest of a file's contents."""
    h = hashlib.sha256()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} does not exist.")
        raise SystemExit(1)

    manifest: dict[str, str] = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if not path.is_file():
            continue
        relative = path.relative_to(REPO_ROOT).as_posix()
        manifest[relative] = sha256_hexdigest(path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

