import os
import re

REPORTS_DIR = "reports"

def report_key(filename):
    """Extract numeric index from report-<n>.txt for sorting."""
    m = re.match(r"report-(\d+)\.txt", filename)
    if m:
        return int(m.group(1))
    return 0

def main():
    try:
        files = [f for f in os.listdir(REPORTS_DIR)
                 if os.path.isfile(os.path.join(REPORTS_DIR, f))]
    except FileNotFoundError:
        return

    files.sort(key=report_key)
    for f in files:
        print(f)

if __name__ == "__main__":
    main()

